  (333, '함께 나눈 대화에 작은 마침표를 찍는 방법은요?', array['다음에 물어볼 한 가지를 남겨요.', '오늘 배운 낱말을 한 번 써 봐요.', '제일 웃긴 순간을 서로 골라 봐요.']),
