  (343, '처음 만난 사람과 기다리는 줄에서 할 만한 소소한 게임은요?', array['앞에 보이는 색으로 끝말잇기요.', '지나간 구름을 보고 동물 고르기요.', '둘이 딱 십 초를 마음속으로 재요.']),
  (350, '상대가 스스로 자랑스러워하는 일을 들으면 뭘 더 묻고 싶어요?', array['어느 순간 해낼 줄 알았는지요.', '처음 한 날과 뭐가 제일 다른지요.', '누구에게 가장 먼저 알려 줬는지요.']),
  (356, '바람 부는 날 둘이 종이 지도를 펴야 한다면요?', array['한쪽 모서리를 팔꿈치로 고정해요.', '일단 벽을 바람막이 삼아 붙어요.', '필요한 칸만 나오도록 작게 접어요.']),
  (366, '생일을 요란하게 보내고 싶지 않은 친구를 어떻게 축하해요?', array['둘만 있을 때 조용히 편지를 건네요.', '점심 메뉴 선택권을 슬쩍 넘겨요.', '날짜 바뀔 때 짧은 축하를 보내요.']),
  (371, '대화 중 누군가 말을 고쳐 했을 때 어떤 반응이 편해요?', array['새로 한 말부터 자연스럽게 이어 가요.', '의미가 바뀐 곳만 한번 물어봐요.', '저도 생각이 바뀌었던 얘길 해요.']),
  (373, '서로 바쁜 한 주에는 무엇으로 안부를 주고받고 싶어요?', array['그날 본 색깔 하나씩 보내고 싶어요.', '점심시간에 딱 한 줄씩 근황을 써요.', '일요일에 웃긴 일 하나씩 몰아서 말해요.']),
  (382, '집까지 빌려 온 물건을 돌려줄 때 나만의 습관이 있나요?', array['빌렸을 때 접힌 모양대로 돌려줘요.', '쓴 만큼 배터리를 다시 채워요.', '잘 쓴 장면을 작은 쪽지로 붙여요.']),
  (387, '대화 상대가 내 말을 잘 들었다는 걸 언제 느끼나요?', array['제가 멈춘 대목에서 질문이 나올 때요.', '제 말에 어울리는 자기 경험을 나눌 때요.', '나중에 그 뒤로 어땠냐고 물을 때요.']),
  (393, '만나자마자 갑자기 소나기가 쏟아진다면 첫 제안은요?', array['처마 밑에서 빗방울 경주나 볼까요?', '따뜻한 차 마시면서 지나가길 기다려요.', '실내 구경 코스로 짧게 바꿔 봐요.']),
  (398, '친구가 혼자 해낸 일이 유난히 뿌듯해 보일 때 해 주는 일은요?', array['직접 시범을 보여 달라고 해요.', '기념할 사진을 본인이 고르게 해요.', '그 일을 시작한 날 얘기도 들어요.']),
  (406, '같이 쓸 공간에 내 취향을 하나만 더할 수 있다면요?', array['누구나 쓰기 편한 무릎 담요요.', '읽은 책을 돌려 볼 작은 바구니요.', '오늘의 신청곡을 적는 빈 종이요.']),
  (411, '나를 도와준 사람 덕에 새로 배우게 된 버릇은 뭔가요?', array['카트 쓸 사람에게 손잡이를 돌려줘요.', '복잡한 길은 그림으로 설명해요.', '남의 충전선을 감을 땐 느슨히 감아요.']),
  (417, '누군가 내 말을 인용해 줘서 기분 좋았던 때가 있나요?', array['제 엉뚱한 단어가 모임 별명이 됐어요.', '제가 알려 준 팁으로 화분이 살았대요.', '친구가 제 건배사를 흉내 내 줬어요.']),
  (425, '둘의 대화가 라디오 코너라면 첫 청취자에게 뭘 물을까요?', array['오늘 들은 가장 좋은 소리는요?', '한 시간 쉬면 뭘 제일 먼저 할래요?', '방금 피식한 장면 하나만 들려주세요.']),
  (428, '마음에 들지 않은 선물을 골랐다는 걸 알면 어떻게 해요?', array['교환하러 같이 가자고 먼저 말해요.', '다음에 기억할 취향을 물어봐요.', '사용할 다른 방법을 같이 궁리해요.']),
  (436, '서로 칭찬을 주고받는 게임에서 먼저 알아봐 주고 싶은 건요?', array['긴장한 사람을 웃게 하는 타이밍이요.', '작은 약속도 적어 두는 부지런함이요.', '모르는 걸 솔직하게 묻는 용기요.']),
  (441, '옆 사람 차례에 주문이 한참 걸릴 때 기다리는 나만의 방식은요?', array['제 주문도 조용히 한번 점검해요.', '진열된 빵 모양을 구경해요.', '뒤에서 바짝 붙지 않고 한 발 물러나요.']),
  (446, '함께 한 일을 돌아보며 상대에게 건네고 싶은 질문은요?', array['또 한다면 뭘 제일 먼저 바꿔 볼까요?', '어느 순간 둘이 제일 손발이 맞았나요?', '다음에는 어떤 역할을 해 보고 싶어요?']),
  (453, '대화 주제가 너무 빨리 넘어갔을 때 어떻게 원래 얘기로 돌아와요?', array['아까 그 우체통 얘기 끝이 궁금해요.', '중간에 놓친 단어 하나를 다시 물어요.', '제 손가락으로 되감기를 그려 봐요.']),
  (457, '친구가 어떤 물건에 애착이 크다면 뭘 물어보겠어요?', array['처음 만난 날이 기억나는지요.', '가장 많이 닳은 곳은 어디인지요.', '이름을 붙였다면 무슨 이름인지요.']),
  (468, '같이 식물을 돌본다면 어떤 식으로 호흡을 맞춰요?', array['물을 준 날 작은 스티커를 붙여요.', '한 사람은 볕을, 다른 사람은 흙을 봐요.', '새잎이 나올 때 번갈아 사진을 찍어요.']),
  (474, '잘 모르는 분야에서 상대가 열정을 보일 때 붙잡히는 부분은요?', array['설명할 때 손짓이 커지는 순간이요.', '아무도 안 본 작은 차이를 찾아낼 때요.', '망쳤던 첫 작품을 꺼내 웃을 때요.']),
  (479, '분실물의 주인을 찾아 준다면 어느 순간이 가장 뿌듯할까요?', array['주인 눈에 물건이 딱 들어온 순간이요.', '잃어버린 줄도 몰랐다며 웃을 때요.', '다시 찾았다는 연락 한 줄을 받을 때요.']),
