  (528, '둘이 처음 협동 요리를 할 때 맡고 싶은 자리는 어디인가요?', array['맛보는 사람에게 작은 숟가락 건네기요.', '타이머 지키고 익은 순서 맞추기요.', '재료를 썰어서 쓸 순서로 줄 세우기요.']),
  (534, '걱정하는 사람 옆에서 말없이 해 줄 수 있는 일이 있나요?', array['마실 물을 손 닿는 곳에 둬요.', '잠깐 바람 쐴 수 있게 외투를 건네요.', '그동안 켜 둔 텔레비전을 살짝 꺼요.']),
  (539, '잘 아는 사람이 추천해 준 물건이 나와 꼭 맞는 이유는요?', array['한 손으로 열리는 걸 기억했어요.', '무향을 좋아한다는 말을 들어 뒀대요.', '가방에 쏙 들어가는 크기를 골랐어요.']),
  (544, '동네 벼룩시장에서 둘이 가게를 열면 어떤 식으로 손님을 맞을까요?', array['물건에 얽힌 재밌는 사연을 들려줘요.', '구경만 해도 된다는 팻말을 붙여요.', '아이 손님용 낮은 진열대도 놓아요.']),
  (551, '처음 대화할 때 서로의 긴장을 덜어 주는 자리는 어디예요?', array['메뉴 그림을 함께 볼 수 있는 자리요.', '거리 풍경이 보이는 나란한 자리요.', '음악 소리가 작은 안쪽 테이블이요.']),
  (554, '약속을 정할 때 상대가 선택하기 편하도록 어떻게 물어봐요?', array['가능한 날을 두 개만 추려 보내요.', '어느 쪽이 오가기 편한지 물어요.', '꼭 피하고 싶은 시간부터 물어요.']),
  (563, '서로 글씨를 바꿔 써 보는 날이라면 무슨 말을 따라 쓸까요?', array['상대가 자주 쓰는 웃음소리요.', '지금 탁자 위의 메뉴 이름이요.', '각자가 가장 예쁘게 쓰는 한 글자요.']),
  (570, '친구가 과정을 즐기는 걸 보며 나도 해 보고 싶어진 일은요?', array['실을 풀었다 다시 뜨는 손뜨개요.', '낙서에 한 줄씩 채색하는 일이요.', '라디오 주파수를 돌려 가며 듣기요.']),
  (576, '함께 만든 것에 이름을 붙일 때 둘의 아이디어를 어떻게 살려요?', array['한 단어씩 내서 이어 붙여 봐요.', '하나는 제목, 하나는 부제로 써요.', '각자 부르다가 더 입에 붙는 걸 남겨요.']),
  (580, '배웅할 때 아무 말 없이도 반가운 몸짓이 있나요?', array['뒤돌아봤을 때 양손으로 흔드는 거요.', '창문 너머로 경례를 흉내 내는 거요.', '손으로 다음 만남 날짜를 그려 줘요.']),
  (583, '상대가 어떤 단어를 잘못 썼지만 뜻은 통하면 어떻게 할까요?', array['이야기 흐름을 살려 그냥 들어요.', '나중에 둘만 있을 때 살짝 알려 줘요.', '그 단어가 떠오른 까닭을 물어봐요.']),
  (589, '친구가 약속에 늦는다고 연락하면 기다리는 시간을 어떻게 써요?', array['근처 가게에서 엽서 한 장 골라요.', '앉아서 밀린 퍼즐 한 칸을 풀어요.', '같이 갈 곳의 마지막 주문 시간을 봐요.']),
  (599, '끝까지 해내지 못한 시도에도 건네고 싶은 칭찬은요?', array['첫날 문을 두드린 용기가 멋졌어요.', '중간에 방법을 바꾼 게 기억나요.', '포기할 때를 스스로 정한 것도 좋아요.']),
  (605, '듣는 사람이 되어 주고 싶은 날엔 어떤 질문으로 시작해요?', array['오늘 다시 보고 싶은 순간 있었어요?', '하다 만 이야기 하나 있어요?', '요새 시간 가는 줄 모르는 일은요?']),
