  (616, '내 편이 되어 준다는 느낌이 드는 작은 행동은 무엇인가요?', array['제가 말할 차례를 조용히 되찾아 줘요.', '낯선 곳에서 나오는 문을 같이 찾아요.', '결과를 묻기 전에 밥부터 사 줘요.']),
  (621, '단둘이 처음 사진 부스에 들어가면 첫 포즈는 어떻게 정할까요?', array['첫 컷은 서로의 표정을 따라 해요.', '가위바위보에서 진 쪽이 연출해요.', '모자 하나씩 골라 거울부터 봐요.']),
  (629, '일을 나눠 맡았는데 한 사람이 먼저 끝나면 뭘 하면 좋을까요?', array['도울 부분이 있는지 물어봐요.', '다 쓴 도구를 씻고 자리를 비워요.', '끝나고 같이 먹을 간식을 챙겨요.']),
  (632, '한 번뿐인 실패를 나중에 웃긴 이야기로 바꾸는 비결은요?', array['제일 당황했던 표정부터 흉내 내요.', '그 일 덕분에 알게 된 팁을 붙여요.', '그때 같이 있던 친구에게 제목을 맡겨요.']),
  (637, '누군가 내 취향을 물었는데 나도 잘 모르면 뭐라고 답해요?', array['최근에 두 번 고른 걸 떠올려요.', '싫지 않았던 것부터 하나씩 말해요.', '둘이 시험 삼아 골라 보자고 해요.']),
  (646, '마트에서 둘이 장을 보다가 계획에 없는 물건이 끌리면요?', array['각자 뜻밖의 물건 하나씩만 골라요.', '일단 한 바퀴 돈 뒤에도 끌리나 봐요.', '장바구니 속 재료와 짝이 맞나 따져요.']),
  (652, '새로운 사람을 다른 친구에게 소개할 때 어떤 점을 먼저 말해요?', array['둘이 동시에 좋아할 만한 취미요.', '최근에 함께 해서 웃겼던 일이요.', '스스로 불리길 좋아하는 별명이요.']),
  (659, '나를 웃기려고 애쓴 사람에게 웃음 말고 뭘 돌려주고 싶어요?', array['그 농담에 꼭 맞는 효과음을 내요.', '다음번엔 제가 준비한 개그를 해요.', '오늘의 명대사라고 쪽지에 적어 줘요.']),
  (666, '낯선 사람의 친절을 다른 사람에게 이어 준다면 어떻게 할까요?', array['뒤에 온 사람에게 반납구를 알려 줘요.', '빈 대여 바구니를 입구로 가져와요.', '유모차가 지나가게 문을 잡아 줘요.']),
  (668, '동행과 다른 것을 보고도 같은 순간을 기억하는 방법은요?', array['돌아와서 각자 한 줄로 묘사해요.', '같은 각도에서 찍은 사진을 비교해요.', '서로 기억한 색깔부터 맞혀 봐요.']),
  (674, '친구에게 나의 서툰 면을 편하게 보여 줄 수 있는 순간은요?', array['서로 처음 하는 공예를 시작할 때요.', '계량하다 밀가루를 옷에 묻혔을 때요.', '같이 길 잃고 단번에 웃음이 날 때요.']),
  (680, '혼자라면 미뤘겠지만 누가 곁에 있어 즐거웠던 일은요?', array['서랍 속 단추를 크기대로 나눴어요.', '밀린 유리병의 라벨을 다 뗐어요.', '굳어 버린 화분 흙을 함께 갈았어요.']),
  (686, '대화 상대에게 두 번째 만남까지 기억해 두고 싶은 건요?', array['마무리 못 한 여행 이야기의 뒷부분이요.', '제일 크게 웃었던 엉뚱한 단어예요.', '다음에 먹어 보고 싶다던 빵이요.']),
  (694, '정중히 사양했는데도 마음은 잘 전해졌다고 느끼는 때는요?', array['다음 기회에 보자고 편하게 웃을 때요.', '이유를 캐묻지 않고 주제를 바꿀 때요.', '필요하면 언제든 얘기하라고 할 때요.']),
  (699, '둘이 같은 물건을 고르다 취향 차이를 발견하면 재밌는 부분은요?', array['색은 같은데 재질 선택이 갈려요.', '한 명은 소리, 한 명은 무게부터 봐요.', '예쁜 포장과 편한 손잡이가 맞붙어요.']),
  (704, '고마워하는 표정 하나를 그림으로 남긴다면 어느 장면인가요?', array['잃어버린 장갑 한 짝을 돌려받는 순간이요.', '넘칠 뻔한 컵을 둘이 붙잡은 순간이요.', '비어 있던 객석에서 친구를 찾은 순간이요.']),
  (711, '내가 진행하는 대화 모임에 규칙을 하나만 붙인다면요?', array['대답 대신 패스를 해도 괜찮아요.', '마지막 한 사람까지 한마디씩 들어요.', '누군가 말한 별명은 허락받고 써요.']),
  (715, '상대 덕분에 시선이 달라진 평범한 풍경이 있나요?', array['친구가 짚어 준 보도블록에 찍힌 잎 자국이요.', '동료가 보여 준 유리창의 두 번째 무지개요.', '조카가 고른 돌멩이 속 웃는 얼굴이요.']),
  (721, '하루의 끝에 둘이 서로에게 작은 숙제를 낸다면요?', array['내일 가장 먼저 들린 소리를 기억해요.', '간식 하나에 새로운 이름을 붙여요.', '길에서 마주친 예쁜 글자 하나를 골라요.']),
  (727, '처음 만난 오늘을 나중에 기억할 별명으로 부른다면요?', array['동시에 물 마시고 같이 웃은 날이요.', '신기하게 신호등이 다 초록이던 날이요.', '메뉴판 뒷면까지 읽어 본 날이요.']);
